<div class="table-wrap"><table><thead><tr><th>Description</th><th>Date</th><th>Category</th><th>Status</th><th class="number">Amount</th><th><span class="sr-only">Open</span></th></tr></thead><tbody>
<?php foreach($entries as $row): ?><tr><td><a class="row-title" href="<?= e(url('entry',['id'=>$row['id']])) ?>"><span class="entry-symbol <?= e($row['type']) ?>"><?= icon($row['type']==='income'?'arrow-down-circle':'wallet') ?></span><span><?= e($row['description']) ?><small><?= e($row['reference'] ?: ($row['contact']??ucfirst($row['type']))) ?></small></span></a></td><td class="nowrap"><?= short_date($row['entry_date']) ?></td><td><?= e($row['category']??'Uncategorized') ?></td><td><?= badge($row['status']) ?></td><td class="number strong <?= $row['type']==='income'?'positive':'' ?>"><?= $row['type']==='income'?'+':'' ?><?= money($row['amount']) ?></td><td><a class="icon-button" title="Open entry" aria-label="Open <?= e($row['description']) ?>" href="<?= e(url('entry',['id'=>$row['id']])) ?>"><?= icon('arrow-up-right') ?></a></td></tr><?php endforeach ?>
<?php if(!$entries): ?><tr><td colspan="6"><div class="empty-state"><?= icon('file-text') ?><h3>No entries yet</h3><p>Your matching transactions will appear here.</p></div></td></tr><?php endif ?>
</tbody></table></div>
